import { z } from "zod";
import { defineAction } from "../../action.js";
import { getBetterAuth, withBetterAuthActionSession, } from "../../server/better-auth-instance.js";
import { PASSWORD_MAX_LENGTH, PASSWORD_MIN_LENGTH, } from "../../shared/password-policy.js";
const currentPasswordSchema = z.string().min(1).max(PASSWORD_MAX_LENGTH);
const newPasswordSchema = z
    .string()
    .min(PASSWORD_MIN_LENGTH)
    .max(PASSWORD_MAX_LENGTH);
export default defineAction({
    description: "Change the password for the signed-in user's account.",
    schema: z.object({
        currentPassword: currentPasswordSchema,
        newPassword: newPasswordSchema,
    }),
    agentTool: false,
    toolCallable: false,
    run: async ({ currentPassword, newPassword }, ctx) => {
        if (!ctx?.userEmail || !ctx.requestHeaders) {
            throw new Error("Not authenticated.");
        }
        const auth = await getBetterAuth();
        return withBetterAuthActionSession(ctx.userEmail, ctx.requestHeaders, async (headers) => auth.api.changePassword({
            body: { currentPassword, newPassword },
            headers,
        }));
    },
});
